 c=b.new_context(viewport={'width':1440,'height':900});seed['view']='result';c.add_init_script('localStorage.setItem("dubbed-studio-lowfi-v1",'+json.dumps(json.dumps(seed))+')');page=c.new_page();page.goto('http://127.0.0.1:5179');page.wait_for_function('!document.querySelector("#result-play").disabled');page.locator('#source-original').click();page.wait_for_timeout(150);styles=page.evaluate('''()=>{let get=s=>{let a=getComputedStyle(document.querySelector(s));return {color:a.color,bg:a.backgroundColor,font:a.fontFamily,size:a.fontSize,line:a.lineHeight,height:document.querySelector(s).getBoundingClientRect().height,transition:a.transitionDuration}};return {selected:get('#source-original'),unselected:get('#source-dub'),play:get('#result-play'),rail:get('.result-transport')}}''');check('Settled selection uses white/dark selected surface',styles['selected']['bg']=='rgb(255, 255, 255)' and styles['selected']['color']=='rgb(32, 32, 32)' and styles['unselected']['color']=='rgb(252, 252, 252)',styles)
