 # Relative luminance contrast of the settled semantic colors is deterministic.
 def lum(rgb):
  v=[int(x)/255 for x in rgb[4:-1].split(',')];v=[x/12.92 if x<=.04045 else ((x+.055)/1.055)**2.4 for x in v];return sum(x*y for x,y in zip(v,[.2126,.7152,.0722]))
